    "73888328b711af8396cd": {"text": {"$ref": "image_answers", "id": "26f52d0e01e3256a161d"}, "review": {"correctness": 40, "visual_detail": 30, "completeness": 15, "clarity": 8, "note": "completeness: omits the distinct lotus-shaped ArtScience Museum near the center-left, one of the visible landmarks the prompt asks to identify and place. Clarity: adds extended skyline and waterfront commentary.", "answer_sha256": "1a502b3f199bb5438b158b3945906b36bbc3793d42e7fa55971c94413a7106fd", "reviewer": "gpt-6-luna"}},
